import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第三卷 潮汐 · 第59章 成人礼前","description":"","frontmatter":{},"headers":[],"relativePath":"第59章_成人礼前.md","filePath":"第59章_成人礼前.md"}'),r={name:"第59章_成人礼前.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第三卷-潮汐-·-第59章-成人礼前" tabindex="-1">第三卷 潮汐 · 第59章 成人礼前 <a class="header-anchor" href="#第三卷-潮汐-·-第59章-成人礼前" aria-label="Permalink to &quot;第三卷 潮汐 · 第59章 成人礼前&quot;">​</a></h1><p>高二冬天，雾气比往常更重。早自习还没开始，走廊尽头的窗户半开着，冷风灌进来，吹得窗帘轻轻鼓起。我坐在座位上，指尖有点凉，桌上摊着学校统一发的卡纸，米白色的，边角印着很淡的潮汐纹。</p><p>叶老师站在讲台上，声音放得很轻，说成人礼是学校很看重的仪式，每个人都要给最想感谢的人写一张卡，可以在仪式上亲手送出，也可以投进门口的信箱，由老师转交。她说完笑了笑，补充了一句，不署名也行，心意到了就好。</p><p>教室里响起一阵很轻的笑声，林小满回头看我，眼睛亮亮的，压低声音说你肯定写给江苒吧。我没接话，只是把卡纸翻了个面，指腹摩挲着纸面粗糙的纹路。陈默在旁边拆了一颗海盐糖，奶香混着一点咸味飘过来，他把糖纸抚平，垫在桌角。</p><p>我想了很久，笔尖悬在半空，墨水在笔尖聚成小小的一点，又落回去。窗外是灰白的天，远处操场的雾还没有散，隐约能听见顾远和秦浩在搬音箱，脚步声和箱子摩擦地面的声音混在一起。广播里试了一段音乐，是从旧的课文录音带里转录的，有点失真，沙沙的，像海浪退下去时留在沙滩上的声音。</p><p>何晓凑过来借笔，她的卡写了一半，收尾画了一颗纸星星。她说那是跟赵晴学的，代表平安。我把另一支笔递给她。她看一眼我空白的卡纸，你还没想好吗。我说快了。</p><p>其实我早就想好了。</p><p>我想写给江苒。</p><p>高二秋天，她把折好的纸星星塞进我的抽屉，一整罐，用玻璃瓶装着，说祝我顺风。我到现在还留着，失眠时会倒出来听听玻璃碰撞的声音。高三开学后，她把那盘旧的课文录音带借给我，里面是她录的海浪声，还有她哼的歌，说压力大时听一听，就当去海边了。</p><p>这些话，我都记得。只是从来没说过谢谢。</p><p>笔尖落下去，我写得很慢。开头只写了江苒两个字，后面空了很久。我想写傍晚她在巷口等我，头发被风吹乱，手里握着化了一半的海盐糖。想写雾散的早晨她跑过操场，衣摆扬起来。想写她生病那次，宋阿婆煮了姜汤，她捧着碗红着眼睛笑。</p><p>写着写着，纸面洇开一小点。是我的手心出汗了。我赶紧用袖口压了压，把那一点晕开的墨压住。陈默瞥了一眼，低声说你这字写得也太用力了，纸都要破了。我笑了笑，把卡往里收了收。</p><p>林小满写完了，举起来给我们看，上面画满图案。她说仪式那天要亲手送给叶老师。何晓点头，说她要送给宋阿婆。教室里渐渐有了说话声。</p><p>我重新提笔，写雾山市的雾，南雾县的潮，写我们一起走过的坡道，写黄昏时海面一样的天。我写得很克制，不敢写太多，怕把喜欢两个字写出来。</p><p>喜欢这两个字，在我心里放了很久，像退潮时藏在石头下面的水，见不得光，一碰就漫出来，漫出来就会慌。</p><p>下课铃响，我的卡只写了一半。叶老师说没写完可以带回去，明早交就行。顾远喊我去帮忙抬东西，我把卡夹进书里。走廊风大，江苒正好从对面走来，怀里抱着节目单，头发上沾着雾水。</p><p>她眼睛弯起来，问我卡写好了吗，声音混在风里。我说还没，声音有点哑。她笑，说我也没写好，想谢的人太多了，写不过来。我看着她，心跳有点快，书页底下那张卡硌着手指，硬硬的，像提醒。</p><p>我想问她，收到没署名的卡会不会认真看，会不会多看一眼。话到嘴边变成一句，你慢慢写，不着急，慢慢写才好看。她点点头，抱着节目单跑远了，发尾在风里晃了一下。</p><p>中午教室没什么人，暖气开得很小，桌面的凉气还在。我把卡拿出来补后半段，写的都是祝愿，愿她平安顺风，愿她听见海浪声时，能想起南雾的冬天，想起有人在雾里陪她走过很长的路，愿她夜里不再慌。写到最后，手有点抖，字都轻了。</p><p>落款的地方，我空着，特意留白，像那张浅黄硬纸条的背面一样，空白着，心里的话反而更重。落款空着，连点都不敢点。</p><p>陈默回来拿水杯，杯子里还冒着热气，看见我盯着卡发呆，问我怎么不装进信封，信封就在讲台上。我说再想想，再看一眼。他坐下来，剥了一颗海盐糖递给我，说甜的能让人胆子大一点，胆子大了话就敢说了。我含着糖，咸甜的味道在舌尖化开，喉咙却有点发紧，甜味被风一吹就淡了。我把卡翻过去，背面朝上，轻轻推到书堆后面，让它贴着墙，背面空白，正面朝墙。</p><p>下午排练成人礼的队形，赵晴拿着名单喊号，声音在雾气里显得有点哑，被风吹散。江苒站在女生队伍中间，偶尔回头看我一眼，笑一下，又转回去，围巾角被风吹起来。风把她的衣角吹起来，我忽然觉得眼睛有点酸，赶紧低下头看脚尖。水泥地上有一层薄薄的水汽，踩上去凉凉的，鞋底摩擦出很轻的声响，像踩在潮上。</p><p>排练结束，天已经暗了，雾更浓，灯光在雾里化开。叶老师抱着收上来的信封箱，站在门口，问还有没有要投的，声音温和。很多人围过去，把信封丢进去，哗啦哗啦的响，像落叶。林小满投完还拍了拍箱子，说仪式感拉满，满满的。何晓挽着赵晴的手，两个人小声说着什么，笑得很开心，热气从嘴里冒出来。</p><p>我摸了摸书包侧袋，那张卡就放在里面，折得很整齐，装在一个空白的信封里，没有写收件人，也没有写寄件人，信封口我折了又折，压得平平的。我的手指在信封边缘摩挲了很久，纸边锋利，割得指腹微微发疼，疼得清醒。陈默推了我一下，问我去不去投，投了就踏实了。我摇摇头，说不去了，声音很轻，像怕被风听见。</p><p>他有点意外，但没多问，只是陪我站了一会儿，两个人站在雾里。雾又起来了，操场那边的灯亮起来，光晕在雾里扩散开，像一颗泡在水里的糖，心也泡在里面。我们往校门口走，旧的课文录音带的声音还从广播里飘出来，断断续续的歌，混着风声，带着潮气。</p><p>走到坡道拐弯处，我停下来，把那封信拿出来，看了一眼，信封的空白让我心里发空，又塞回去，指尖在口袋里握紧。江苒的名字在我心里念了一遍，又念了一遍，舌尖抵着上颚，始终没有出声，怕一出声就散了。风把远处的潮声送过来，一下，又一下，拍在坡道上。</p><p>晚上回到家，屋里开了暖气，窗上凝着薄薄的水汽。我把那张卡压在玻璃瓶底下，瓶身温热，纸星星的光透过瓶身，落在卡纸上，碎碎的，像星光落在纸面。窗外雾气未散，明天就是成人礼了，所有人都会穿上整齐的衣服，站在雾气里，说出准备好的感谢。只有我知道，有一张卡，写好了，折好了，却不会被送出，它会一直空白着，留在瓶底。</p><p>手机震了一下，是江苒发来的消息，问我明天穿哪件外套，雾大，怕冷，夜里别冻着。我回了两个字，随意，手指有点凉。她回了一个笑脸，又问我卡写给谁了，是不是写给叶老师。我盯着那行字看了很久，打了几个字，又一个一个删掉，屏幕亮着，照得手指发白。</p><p>窗外风声渐紧，玻璃瓶里的纸星星轻轻晃了一下，碰出很轻的响。我把台灯调暗，心想，明天仪式结束，人群散去，雾气被阳光撕开的时候，她会不会发现，有个人把最重的一句话，藏在了最轻的纸里，而那张纸，永远不会递到她手上。</p>',29)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
